import java.util.Scanner

val s = CharArray(220)
var n: Long = 0
var len: Long = 0

fun check(a: Long): Long {
    var i: Long = 1
    while (i <= a - n) {
        if (s[(len - i).toInt()] != s[(len - i - a).toInt()]) {
            return 0
        }
        i++
    }
    return 1
}

fun main() {
    val scanner = Scanner(System.`in`)
    val inputStr = scanner.next()
    val sChars = inputStr.toCharArray()
    for (i in sChars.indices) {
        s[i] = sChars[i]
    }
    len = inputStr.length.toLong()
    n = scanner.nextLong()

    var i: Long
    var k: Long
    var j: Long
    var ans: Long = 0
    var key: Long
    var max: Long
    var min: Long
    var temp: Long = 0

    if (n > len) {
        min = (len + n) / 2
    } else {
        min = n
    }

    max = (len + n) / 2

    i = 0
    while (i < len) {
        j = 1
        while (j * 2 + i <= len) {
            key = 1
            k = 1
            while (k <= j) {
                if (s[(i + k - 1).toInt()] != s[(i + k + j - 1).toInt()]) {
                    key = 0
                }
                k++
            }
            if (key == 1L) {
                if (j > temp) {
                    temp = j
                }
            }
            j++
        }
        i++
    }

    i = max
    while (i >= min && ans == 0L) {
        if (check(i) == 1L) {
            ans = i
        }
        i--
    }

    if (min > ans) {
        ans = min
    }
    if (temp > ans) {
        ans = temp
    }

    print(2 * ans)
}

